WITH "golem_contributions" AS MATERIALIZED (SELECT "golem_limited_contributions"."golem_c0" AS "golem_c0", COUNT(*) OVER () AS "golem_contribution_count" FROM (SELECT "golem_j0"."name" AS "golem_c0" FROM "posts" AS "golem_a0" INNER JOIN "users" AS "golem_j0" ON ("golem_j0"."id" = "golem_a0"."author_id" AND (("golem_j0"."id" IS NOT NULL AND ("golem_j0"."id" = ?1)))) WHERE ("golem_a0"."author_id" IS NOT NULL AND ("golem_a0"."author_id" = ?2)) LIMIT ?3) AS "golem_limited_contributions"), "golem_groups" AS MATERIALIZED (SELECT "golem_limited_groups".*, COUNT(*) OVER () AS "golem_intermediate_count" FROM (SELECT ("golem_contributions"."golem_c0" COLLATE BINARY) AS "golem_d0", COUNT(*) AS "golem_m0", MAX("golem_contributions"."golem_contribution_count") AS "golem_contribution_count" FROM "golem_contributions" AS "golem_contributions" GROUP BY ("golem_contributions"."golem_c0" COLLATE BINARY) LIMIT ?4) AS "golem_limited_groups") SELECT "golem_guarded"."golem_d0" AS "golem_d0", "golem_guarded"."golem_m0" AS "golem_m0", "golem_guarded"."golem_contribution_count" AS "golem_contribution_count", "golem_guarded"."golem_intermediate_count" AS "golem_intermediate_count", "golem_guarded"."golem_guard_row" AS "golem_guard_row" FROM (SELECT "golem_visible"."golem_d0" AS "golem_d0", "golem_visible"."golem_m0" AS "golem_m0", "golem_visible"."golem_contribution_count" AS "golem_contribution_count", "golem_visible"."golem_intermediate_count" AS "golem_intermediate_count", ROW_NUMBER() OVER (ORDER BY "golem_visible"."golem_d0" IS NOT NULL ASC, ("golem_visible"."golem_d0" COLLATE BINARY) ASC) AS "golem_page_ordinal", 0 AS "golem_guard_row" FROM (SELECT "golem_grouped"."golem_d0" AS "golem_d0", "golem_grouped"."golem_m0" AS "golem_m0", "golem_grouped"."golem_contribution_count" AS "golem_contribution_count", "golem_grouped"."golem_intermediate_count" AS "golem_intermediate_count" FROM "golem_groups" AS "golem_grouped" ORDER BY "golem_grouped"."golem_d0" IS NOT NULL ASC, ("golem_grouped"."golem_d0" COLLATE BINARY) ASC LIMIT ?5) AS "golem_visible" UNION ALL SELECT NULL AS "golem_d0", NULL AS "golem_m0", COALESCE(MAX("golem_guard_groups"."golem_contribution_count"), 0) AS "golem_contribution_count", COALESCE(MAX("golem_guard_groups"."golem_intermediate_count"), 0) AS "golem_intermediate_count", 0 AS "golem_page_ordinal", 1 AS "golem_guard_row" FROM "golem_groups" AS "golem_guard_groups") AS "golem_guarded" ORDER BY "golem_guarded"."golem_guard_row" ASC, "golem_guarded"."golem_page_ordinal" ASC